import{_ as s,o as n,c as a,a3 as t}from"./chunks/framework.BzWmN0d8.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1788354533000}'),i={name:"guide/architecture.md"};function o(r,e,l,c,p,d){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p><code>lograil</code> is organized in layers so each concern stays isolated and testable. A log call flows through them in a predictable order.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  log.info(message, ...args)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │   Logger      │  builds a structured LogEntry (timestamp, scope,</span></span>
<span class="line"><span>   │  (facade)     │  context, metadata, error, level)</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │   Pipeline     │  1. Filters  — drop entries (e.g. by level/scope)</span></span>
<span class="line"><span>   │                │  2. Processors — transform/enrich/redact/serialize</span></span>
<span class="line"><span>   │                │  3. Formatter — serialize to string/JSON</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │  Plugins      │  intercept each entry asynchronously (may drop/modify),</span></span>
<span class="line"><span>   │               │  and can add transports / reshape the pipeline at runtime</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │  Transports   │  final sinks: console, rotating file, IPC, OTLP, custom</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          ▲</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │  Runtime       │  isolates env differences (clock, pid, fs, defaults)</span></span>
<span class="line"><span>   │  Adapter       │  — auto-detected, or supplied explicitly</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Context  — persistent structured fields attached to every entry (plus an</span></span>
<span class="line"><span>             optional ambient async context).</span></span></code></pre></div><ul><li><strong>Logger</strong> turns a call into a <code>LogEntry</code>. The first argument may be a <code>string</code>, an <code>Error</code>, or any value (objects are kept structured). The entry carries <code>context</code> (persistent, inherited request-scoped data) and <code>metadata</code> (per-entry, usually injected by processors — see <a href="./context">Context &amp; Metadata</a> for the distinction).</li><li><strong>Pipeline</strong> runs <code>Filter</code>s (returning <code>false</code> drops the entry), then <code>Processor</code>s (in order, for enrichment, redaction, serialization, …), then a <code>Formatter</code> that produces the on-wire representation. Built-in processors such as <code>createRedactProcessor</code> and <code>createSerializeProcessor</code> plug in here.</li><li><strong>Plugins</strong> run after the pipeline via an async <code>intercept</code> hook per entry. They can drop an entry (return <code>null</code>) or rewrite it, and they receive a <code>PluginContext</code> to reconfigure the logger at runtime.</li><li><strong>Transports</strong> are the sinks (<code>console</code>, <code>rotating file</code>, <code>IPC</code>, <code>OTLP</code>, or your own). A transport&#39;s <code>write</code> may be async; when it is, the logger awaits it during <code>flush()</code> / <code>destroy()</code>. Each transport may also declare its own <code>level</code> to filter independently.</li><li><strong>Runtime Adapter</strong> abstracts the environment (Web / Node / Electron), so the same logger code runs everywhere.</li><li><strong>Context</strong> is merged into every entry&#39;s <code>context</code> field; scoped loggers get an isolated child context. An <strong>ambient (async) context</strong> — request-scoped fields kept via <code>AsyncLocalStorage</code> and auto-inherited across <code>await</code> — is layered on top (browser: no-op).</li></ul><h2 id="asynchrony-lifecycle" tabindex="-1">Asynchrony &amp; lifecycle <a class="header-anchor" href="#asynchrony-lifecycle" aria-label="Permalink to &quot;Asynchrony &amp; lifecycle&quot;">​</a></h2><p>Logging is synchronous from the caller&#39;s perspective, but writes are drained through an internal queue so async transports and plugin interception never block your code:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;done&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// returns immediately</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flush</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// wait until the queue (incl. async writes) is empty</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flush, tear down plugins, close transports</span></span></code></pre></div><p>Because plugin <code>onEntry</code> hooks are awaited and chained, and async transport writes are queued, calling <code>flush()</code> (or <code>destroy()</code>) before process exit guarantees no buffered logs are lost. The Logger wires flush / crash behaviour through the runtime&#39;s <code>lifecycle</code> hooks, so <code>autoFlushOnExit</code> (or <code>attachExitHandlers</code>) flushes on host exit — Node <code>beforeExit</code> / <code>SIGINT</code> / <code>SIGTERM</code>, Electron <strong>main</strong> <code>app</code> <code>before-quit</code> / <code>will-quit</code>, Web <code>pagehide</code> / <code>visibilitychange</code> — and <code>watchUncaughtErrors</code> logs uncaught exceptions / unhandled rejections as <code>fatal</code> before exiting. <code>redirectConsole</code> bridges <code>console.*</code> into the logger.</p><h2 id="where-filtering-happens" tabindex="-1">Where filtering happens <a class="header-anchor" href="#where-filtering-happens" aria-label="Permalink to &quot;Where filtering happens&quot;">​</a></h2><p>There are three independent gates:</p><ol><li><strong>Logger-level gate</strong> — <code>setLevel</code> drops entries below a threshold before they enter the pipeline, so cheaply-discarded entries never cost processing.</li><li><strong>Pipeline filters</strong> — arbitrary predicates (<code>createLevelFilter</code>, <code>createScopeFilter</code>, <code>createSampler</code>, <code>combineFilters</code>, custom) run inside the pipeline.</li><li><strong>Per-transport level</strong> — each transport may declare its own <code>level</code>; entries below it are skipped by that transport only, so one logger can fan out (e.g. <code>error</code>+ to a remote sink while writing everything to a file).</li></ol><h2 id="why-it-s-structured-this-way" tabindex="-1">Why it&#39;s structured this way <a class="header-anchor" href="#why-it-s-structured-this-way" aria-label="Permalink to &quot;Why it&#39;s structured this way&quot;">​</a></h2><ul><li><strong>Separation</strong>: formatting and destination are decoupled — one entry can go to the console and a file with different formats.</li><li><strong>Composability</strong>: filters/processors/transports are plain functions/objects, easy to unit test and reuse.</li><li><strong>Extensibility</strong>: plugins can reshape the pipeline and add sinks at runtime without touching application code.</li><li><strong>Portability</strong>: the runtime adapter means the same API works in Web, Node and Electron, including the renderer→main log aggregation in Electron.</li></ul>`,14)])])}const u=s(i,[["render",o]]);export{g as __pageData,u as default};
